SELECT COUNT(*) AS NumComments
FROM comments
WHERE PostId = (SELECT Id FROM posts WHERE ViewCount = 1910);

SELECT CAST(COUNT(CASE WHEN strftime('%Y', CreationDate) = '2010' THEN Id END) AS REAL) 
     / COUNT(CASE WHEN strftime('%Y', CreationDate) = '2011' THEN Id END) AS vote_ratio
FROM votes;

SELECT DisplayName, Age
FROM users
WHERE Views = (SELECT MAX(Views) FROM users);

SELECT LastEditDate, LastEditorUserId
FROM posts
WHERE Title = 'Detecting a given face in a database of facial images';

SELECT OwnerUserId
FROM posts
WHERE FavoriteCount = (SELECT MAX(FavoriteCount) FROM posts);

SELECT Id
FROM users
WHERE Age = (SELECT MIN(Age) FROM users);

SELECT DisplayName
FROM users
WHERE Reputation = (SELECT MAX(Reputation) FROM users);

SELECT COUNT(*) AS TotalPostsAboveAverageViews
FROM posts
WHERE ViewCount > (SELECT AVG(ViewCount) FROM posts);

SELECT COUNT(*) AS comment_count
FROM comments
WHERE PostId = (SELECT Id FROM posts WHERE Score = (SELECT MAX(Score) FROM posts));

SELECT Reputation, Views
FROM users
WHERE DisplayName = 'Jarrod Dixon';

SELECT 100.0 * SUM(CASE WHEN Currency = 'EUR' THEN 1 ELSE 0 END) / COUNT(*) AS percentage_kam_euro
FROM customers
WHERE Segment = 'KAM';

SELECT player_api_id
FROM Player_Attributes
WHERE overall_rating = (SELECT MAX(overall_rating) FROM Player_Attributes);

SELECT preferred_foot
FROM Player_Attributes
WHERE potential = (SELECT MIN(potential) FROM Player_Attributes);

SELECT team_fifa_api_id
FROM Team_Attributes
WHERE buildUpPlaySpeed > 50 AND buildUpPlaySpeed < 60;

SELECT team_short_name
FROM Team
WHERE team_long_name = 'Queens Park Rangers';

SELECT player_name
FROM (
    SELECT player_name, RANK() OVER (ORDER BY height DESC) AS rnk
    FROM Player
) ranked
WHERE rnk = 1;

SELECT A3 AS branch_location, A2 AS district_name
FROM district
WHERE CAST(A13 AS REAL) = (SELECT MAX(CAST(A13 AS REAL)) FROM district);

SELECT first_name, last_name, email
FROM member
WHERE position = 'Secretary';

SELECT SUM(type = 'Community Service') * 100.0 / COUNT(event_id) AS percentage
FROM event
WHERE event_date BETWEEN '2019-01-01' AND '2019-12-31';

SELECT SUM(cost) AS total_cost_parking
FROM expense
WHERE expense_description = 'Parking';

SELECT SUM(cost) AS total_expense
FROM expense
WHERE expense_date = '2019-08-20';

SELECT COUNT(*) AS total_superheroes_without_full_name
FROM superhero
WHERE full_name IS NULL;

SELECT superhero_name,
       SUM(height_cm) OVER () / (SELECT COUNT(*) FROM superhero) AS average_height
FROM superhero;

SELECT full_name
FROM superhero
WHERE weight_kg = 0 OR weight_kg IS NULL;

SELECT hero_id
FROM hero_attribute
WHERE attribute_value = (SELECT MIN(attribute_value) FROM hero_attribute);

SELECT full_name
FROM superhero
WHERE superhero_name = 'Alien';

SELECT CAST(COUNT(CASE WHEN Admission = '+' THEN ID END) AS REAL) / COUNT(CASE WHEN Admission = '-' THEN ID END) AS percentage
FROM Patient
WHERE SEX = 'M';

SELECT CAST(SUM(CASE WHEN Admission = '+' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) AS percentage
FROM Patient
WHERE strftime('%Y', Birthday) BETWEEN '1930' AND '1940';

SELECT SUM(SEX = 'F') * 100.0 / COUNT(SEX) AS percentage_women
FROM Patient
WHERE strftime('%Y', Birthday) = '1980' AND Diagnosis = 'RA';

SELECT element
FROM atom
WHERE molecule_id = 'TR004';

SELECT DISTINCT element
FROM atom
WHERE atom_id NOT IN (SELECT atom_id FROM connected);

SELECT SUM(CASE WHEN bond_type = ' = ' THEN 1 ELSE 0 END) * 100.0 / COUNT(bond_id) AS percent
FROM bond
WHERE molecule_id = 'TR047';

SELECT COUNT(*) 
FROM molecule 
WHERE label = '+';
